const $=s=>document.querySelector(s),money=n=>'₹'+n.toLocaleString('en-IN',{maximumFractionDigits:2,minimumFractionDigits:0}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',chevron:'m9 5 7 7-7 7',chart:'M4 19V5m0 14h16M8 14l4-5 4 2 4-6',book:'M12 6v15M12 6C9 3 5 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 2Z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6',check:'m5 12 4 4L19 6',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5V10Zm7 4v3',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',wallet:'M3 6h17v15H3V6Zm0 0V3h14v3m-3 6h7v5h-7v-5Z',pie:'M11 3a9 9 0 1 0 10 10H11V3Zm4-1v7h7a9 9 0 0 0-7-7Z',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',close:'m6 6 12 12M6 18 18 6',info:'M12 11v6m0-10v.1M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',bookmark:'M6 3h12v18l-6-4-6 4V3Z',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15ZM16 16l5 5',play:'m8 4 12 8-12 8V4Z'};
function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.chart}"/></svg>`}
let state;try{state=Engine.restore(localStorage.getItem('groww-learn-v1'));}catch{state=Engine.initial();}
let page=Engine.landing(state),lesson=0,selection=null,checked=false,scenarioAction=null,scenarioReason=null,period='1Y',stockTab='Overview',modalReturnFocus=null,renderedScenario=-1;
function save(){try{localStorage.setItem('groww-learn-v1',JSON.stringify(state));}catch{toast('Your browser could not save progress. Keep this tab open.');}}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.opacity=0,3500);}
function go(p){if(!state.onboardingComplete&& !['welcome','recommend'].includes(p))p=Engine.landing(state);page=p;selection=null;checked=false;scenarioAction=null;scenarioReason=null;closeSheet();render();window.scrollTo({top:0,behavior:'instant'});}
const modules=[
 {title:'Understand the business',subtitle:'Know what you are investing in',time:'2 min',heading:'A stock is a piece of a business.',intro:'Before looking at a price chart, understand what the company does and how it earns money.',content:`<div class="flow"><div>Businesses<small>The customers</small></div>${icon('arrow',15)}<div>IT services<small>What TCS provides</small></div>${icon('arrow',15)}<div>Revenue<small>What it earns</small></div></div><p>For this learning example, TCS provides technology and consulting services to businesses. Customers pay for services such as managing technology systems and delivering digital projects.</p><div class="concept"><strong>Revenue is not profit.</strong><br>Revenue is money earned from customers. Profit is what remains after the relevant costs and expenses.</div><p>Look for who pays the company, what they pay for, and what could make them stop. Recognising a brand is a starting point—not a complete investment case.</p>`,question:'A familiar company has a popular brand. What should you check first?',options:['Whether its share price rose yesterday.','How it makes money and what could affect demand.','Whether people online are buying it.'],correct:1,feedback:'Understanding the business gives you a basis for evaluating its numbers and risks. Familiarity alone does not establish investment quality.'},
 {title:'Look beyond the growth',subtitle:'Connect revenue, profit, and margins',time:'3 min',heading:'More revenue. But more profit?',intro:'Growth matters, but the relationship between revenue and costs helps you understand its quality.',content:`<div class="row"><h3>Revenue over time</h3><span class="subtle">Illustrative index</span></div><div class="chartbox"><div class="bar" style="height:48%"><b>100</b><span>Year 1</span></div><div class="bar" style="height:59%"><b>112</b><span>Year 2</span></div><div class="bar" style="height:68%"><b>124</b><span>Year 3</span></div><div class="bar" style="height:78%"><b>137</b><span>Year 4</span></div><div class="bar" style="height:90%"><b>151</b><span>Year 5</span></div></div><p>In this sample dataset, revenue rises from an index of 100 to 151. That tells us sales grew. It does not, on its own, tell us whether profitability improved.</p><div class="concept"><strong>Operating margin = operating profit ÷ revenue.</strong><br>If revenue rises 10% but operating profit rises only 2%, operating margin falls. Investigate why costs grew faster.</div>`,question:'Revenue rises 10%, while operating profit rises 2%. What can you conclude?',options:['Profitability must have improved.','The company is definitely a poor investment.','Sales grew, but operating margin fell; the reason needs investigation.'],correct:2,feedback:'Operating profit grew more slowly than revenue, so operating margin fell. That is a reason to investigate costs, not a complete buy or sell signal.'},
 {title:'Put the price in context',subtitle:'Understand valuation and comparisons',time:'3 min',heading:'A good business still has a price.',intro:'Valuation helps connect the price of a share to the business behind it.',content:`<div class="concept"><strong>Price-to-earnings (P/E)</strong><br>A P/E of 28× means investors pay ₹28 for each ₹1 of the company’s annual earnings per share, using the earnings measure selected.</div><div class="metric"><span>TCS · sample P/E</span><strong>28×</strong></div><div class="metric"><span>Infosys · sample P/E</span><strong>25×</strong></div><div class="metric"><span>Peer group · sample median</span><strong>26×</strong></div><p>A higher P/E might reflect stronger expected growth or perceived business quality. It could also reflect overly optimistic expectations. Compare similar businesses and the same earnings period.</p><p>These sample values are for learning. They are not current market valuations.</p>`,question:'TCS has a higher sample P/E than its peer. What does that tell you?',options:['It is automatically overpriced.','The market pays more per rupee of earnings; investigate the expectations behind that premium.','It will deliver a higher return.'],correct:1,feedback:'P/E describes a price relationship. Whether the premium is justified depends on growth, risk, business quality, and the basis of comparison.'},
 {title:'Know what could change',subtitle:'Identify risk and challenge your view',time:'2 min',heading:'What could make your view wrong?',intro:'A thoughtful decision includes uncertainty. Ask what evidence would cause you to reconsider.',content:`<div class="metric"><span>Customer spending slows</span>${icon('layers',18)}</div><p>Businesses may delay technology projects, affecting revenue growth.</p><div class="metric"><span>Costs grow faster than revenue</span>${icon('chart',18)}</div><p>Higher delivery costs could reduce margins even when sales rise.</p><div class="metric"><span>Expectations are too optimistic</span>${icon('pie',18)}</div><p>A business can grow and still disappoint the expectations reflected in its share price.</p><div class="concept"><strong>Write a decision rule.</strong><br>“I would revisit my view if customer demand weakened for several quarters or margins fell without a convincing explanation.”</div>`,question:'Which statement shows a useful approach to risk?',options:['I will identify what could go wrong and what evidence would change my view.','A well-known company cannot lose value.','I only need to review risk after the price falls.'],correct:0,feedback:'Identifying risks and what would change your assessment creates a clearer decision process. It does not remove uncertainty or guarantee a return.'}
];
function title(eyebrow,heading,right=''){return `<div class="page-top"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1></div>${right}</div>`}
function back(to,label='Back'){return `<button class="back" data-go="${to}">${icon('back',16)} ${label}</button>`}
function note(){return `<div class="bottomnote">An independent case-study prototype inspired by Groww. No real transactions.<br>All prices, financials, and scenarios are illustrative sample data.</div>`}
function evidence(){return `<aside class="stack evidence"><div class="panel"><div class="evidence-title">Your company in focus</div><div class="company"><div class="companylogo">tcs</div><div><strong>Tata Consultancy Services</strong><small>IT services · Learning example</small></div></div><div class="metric"><span>Sample share price</span><strong>₹3,200</strong></div><div class="metric"><span>Sample P/E</span><strong>28×</strong></div><div class="metric"><span>Sample operating margin</span><strong>24%</strong></div><div class="data-note">Fictional figures prepared for this prototype. Not live company data.</div></div><div class="panel"><div class="row"><h3>Need a simpler explanation?</h3>${icon('spark')}</div><p>Explore the concepts at your own pace.</p><button class="text-link" data-action="ai">Ask the demo assistant ${icon('arrow',15)}</button></div><div class="inline-note">${icon('shield',18)}<span>Your progress stays on this browser. Learn without connecting an investment account.</span></div></aside>`}
function home(){return `${title('YOUR GUIDED INVESTING EXPERIENCE','Groww First Steps',`<button class="text-link" data-action="settings">Settings ${icon('settings',15)}</button>`)}<section class="hero"><div class="hero-copy"><span class="tag">${icon('spark',12)} BUILT FOR YOUR FIRST STEP</span><h2>Build understanding.<br><em>Before you invest.</em></h2><p>Choose an investment track. Learn the essentials.<br>Complete its lessons to unlock investing.</p></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="art-card"><div class="mini"></div><div class="mini" style="width:30px;opacity:.45"></div><div class="art-bars"><i style="height:33%"></i><i style="height:52%"></i><i style="height:73%"></i><i style="height:100%"></i></div></div><div class="floating book">${icon('book',28)}</div><div class="floating spark">${icon('spark',27)}</div></div></section><div class="steps"><div class="step"><span>${icon('book',16)}</span><div>Learn<small>Know the essentials</small></div></div>${icon('chevron',14).replace('<svg','<svg class="step-arrow"')}<div class="step"><span>${icon('wallet',16)}</span><div>Practice<small>Use virtual money</small></div></div>${icon('chevron',14).replace('<svg','<svg class="step-arrow"')}<div class="step"><span>${icon('shield',16)}</span><div>Reflect<small>Review your thinking</small></div></div></div><div class="section-heading"><div><h2>Where would you like to begin?</h2><p>Choose what you want to invest in. Start with its lessons.</p></div><span class="subtle">Learn at your own pace</span></div><div class="track-grid"><article class="track featured"><div class="track-top"><div class="track-icon">${icon('chart',24)}</div><span class="badge">${Engine.stocksComplete(state)?'INVESTING UNLOCKED':'LEARN TO UNLOCK'}</span></div><h3>Stocks</h3><p>Learn to evaluate a business and its risks. Complete this track to unlock stock investing.</p><div class="track-footer"><span>4 short modules</span><span>·</span><span>~10–15 min</span></div><button class="btn full" data-action="enroll">${Engine.stocksComplete(state)?'Review Stocks course':state.enrolled?'Continue Stocks lessons':'Start Stocks lessons'} ${icon('arrow',17)}</button></article><article class="track"><div class="track-top"><div class="track-icon purple">${icon('pie',24)}</div><span class="badge soon">COMING SOON</span></div><h3>Mutual funds</h3><p>Get to know funds, diversification, and investing regularly.</p><div class="track-footer"><span>A foundation for your goals</span></div><button class="btn locked full" data-action="soon-funds">${icon('lock',14)} View track preview</button></article><article class="track"><div class="track-top"><div class="track-icon blue">${icon('layers',24)}</div><span class="badge soon">COMING SOON</span></div><h3>ETFs</h3><p>Explore baskets of investments and how an index works.</p><div class="track-footer"><span>The bigger picture, explained</span></div><button class="btn locked full" data-action="soon-etfs">${icon('lock',14)} View track preview</button></article></div><div class="trust-row"><span>${icon('shield',15)} No real money at risk</span><span>${icon('clock',15)} Go at your own pace</span><span>${icon('check',15)} No investing experience needed</span></div>${note()}`}
function curriculum(){const n=state.completed.length;return `${back('home','All learning tracks')}${title('FIRST STEPS · STOCKS FOUNDATION','Small steps. Clearer decisions.')}<div class="twocol"><div class="stack"><div class="panel"><div class="row"><span class="tag">${icon('book',12)} STOCKS FOUNDATION</span><span class="subtle">${n} of 4 complete</span></div><div class="progress" aria-label="${n*25}% complete"><i style="width:${n*25}%"></i></div><p>Learn through one company, then practise with ₹10,000 in virtual money. ${state.interfaceMode==='classic'?'You can open any module, or jump straight into practice.':'Complete all four lessons to unlock demo stock investing. Each lesson builds on the last; your progress is saved.'}</p></div>${modules.map((m,i)=>{const done=state.completed.includes(i),locked=state.interfaceMode==='guided'&&i>0&&!state.completed.includes(i-1);return `<button class="module ${locked?'islocked':''}" data-module="${i}" aria-label="${m.title}${locked?', locked':''}"><span class="num">${done?icon('check',18):String(i+1).padStart(2,'0')}</span><span><strong>${m.title}</strong><small>${m.subtitle} · ${m.time}</small></span><span class="end">${icon(locked?'lock':'chevron',17)}</span></button>`}).join('')}<div class="unlock-banner"><span class="num">${icon(Engine.stocksComplete(state)?'check':'lock',20)}</span><div><strong>${Engine.stocksComplete(state)?'Stock investing unlocked':'Stock investing unlocks after this course'}</strong><small>${n} of 4 lessons complete · Demo transactions only</small></div>${Engine.stocksComplete(state)?'<button class="text-link" data-go="stock">View stock →</button>':'<button class="text-link" data-action="mock-buy">See requirements →</button>'}</div><button class="module ${n<4&&state.interfaceMode==='guided'?'islocked':''}" data-action="start-practice"><span class="num">${icon('wallet',19)}</span><span><strong>Put your thinking into practice</strong><small>₹10,000 virtual money · 3 scenarios</small></span><span class="end">${icon(n<4&&state.interfaceMode==='guided'?'lock':'arrow',17)}</span></button></div>${evidence()}</div>${note()}`}
function lessonPage(){const m=modules[lesson];return `${back('curriculum','Your learning path')}<div class="twocol"><section class="panel"><div class="row"><span class="eyebrow">MODULE ${lesson+1} OF 4</span><span class="subtle">${m.time} · Stocks foundation</span></div><div class="progress"><i style="width:${(lesson+1)*25}%"></i></div><h1 class="lesson-title">${m.heading}</h1><p class="lesson-sub">${m.intro}</p>${m.content}<div class="quiz"><div class="eyebrow">A QUICK CHECK</div><h3>${m.question}</h3>${m.options.map((o,i)=>`<button class="option ${selection===i?'selected':''}" data-answer="${i}" aria-pressed="${selection===i}" ${checked?'disabled':''}><span class="radio"></span>${o}</button>`).join('')}${checked?`<div class="feedback ${selection===m.correct?'':'review'}" role="status"><strong>${selection===m.correct?'That’s the key idea.':'A useful distinction to revisit.'}</strong><br>${m.feedback}</div>`:''}<div class="actions">${checked?`<button class="btn" data-action="next-module">${lesson===3?'Complete Stocks foundation':'Next module'} ${icon('arrow',16)}</button>`:`<button class="btn" data-action="check-answer" ${selection===null?'disabled':''}>Check understanding ${icon('arrow',16)}</button>`}</div></div></section>${evidence()}</div>${note()}`}
function practice(){const value=state.cash+state.units*state.price,pnl=value-10000;return `${back('curriculum','Your learning path')}${title('PRACTICE · NO REAL MONEY','Room to learn. Space to try.',`<button class="text-link" data-action="history">Activity ${icon('clock',15)}</button>`)}<div class="twocol"><div class="stack"><div class="panel"><div class="row"><span class="subtle">Total practice value</span><span class="pill">VIRTUAL MONEY</span></div><div class="balance">${money(value)}</div><div class="${pnl<0?'negative':'positive'}" style="font-size:12px">${pnl>=0?'+':''}${money(pnl)} simulated gain / loss</div><div class="balancegrid"><div><small>Available cash</small><strong>${money(state.cash)}</strong></div><div><small>Holdings value</small><strong>${money(state.units*state.price)}</strong></div></div>${state.units?`<div class="row"><div class="company"><div class="companylogo">tcs</div><div><strong>TCS</strong><small>${state.units} whole practice share${state.units>1?'s':''} · ${money(state.price)} each</small></div></div><strong>${money(state.units*state.price)}</strong></div><div class="footer-actions"><button class="btn secondary" data-action="virtual-buy">Buy virtual shares</button><button class="btn ghost" data-action="virtual-sell">Sell virtual shares</button></div>`:`<div class="empty">${icon('wallet',35)}<h3>${state.transactions.length?'Your virtual cash is ready.':'Your first practice investment.'}</h3><p>Choose whole shares at an illustrative price.<br>The rest stays as available virtual cash.</p><button class="btn" data-action="virtual-buy">Buy virtual TCS ${icon('arrow',16)}</button></div>`}</div><div class="panel"><div class="row"><span class="eyebrow">THE DECISION LAB</span><span class="subtle">${state.scenario} of 3 reviewed</span></div><h2 style="margin-top:15px">${state.scenario===3?'Your reflections are ready.':'What happens when things change?'}</h2><p>Work through three fictional situations. Decide what you would do, then explain why. Your reasoning matters more than the price movement.</p><button class="btn full" data-action="scenario" ${!state.transactions.length?'disabled':''}>${state.scenario===3?'View practice report':state.scenario?'Continue scenarios':'Start the first scenario'} ${icon('arrow',16)}</button>${!state.transactions.length?'<p class="subtle">Make a virtual purchase to begin.</p>':''}</div></div><aside class="stack"><div class="panel"><h3>How practice works</h3><p>01 &nbsp; Allocate virtual money<br>02 &nbsp; Read each fictional update<br>03 &nbsp; Choose an action and a reason<br>04 &nbsp; Reflect on the evidence</p><div class="concept">Your scenario choices record your thinking. They do not place orders. Use the portfolio controls to make virtual trades.</div></div><div class="inline-note">${icon('info',18)}<span>Educational simulation. Price changes are illustrative and do not predict actual market returns.</span></div></aside></div>${note()}`}
function scenario(){const i=state.scenario,s=Engine.scenarios[i];renderedScenario=i;if(!s)return report();Engine.applyScenario(state,i);save();return `${back('practice','Practice portfolio')}<div class="twocol"><section class="panel"><div class="row"><span class="scenario-label">SCENARIO ${i+1} / 3</span><span class="pill">${s.tag}</span></div><h1 class="lesson-title" style="margin-top:24px">${s.headline}</h1><p class="lesson-sub">${s.body}</p><div class="balancegrid"><div><small>Simulated TCS price</small><strong>${money(state.price)}</strong></div><div><small>This scenario’s movement</small><strong class="${s.change<0?'negative':'positive'}">${s.change>0?'+':''}${Math.round(s.change*100)}%</strong></div></div><h3>What would you consider doing?</h3><div class="scenario-actions">${['Hold','Buy more','Sell','Need more information'].map(a=>`<button class="choice ${scenarioAction===a?'selected':''}" data-decision="${a}" aria-pressed="${scenarioAction===a}">${a}</button>`).join('')}</div><div class="quiz"><div class="eyebrow">EXPLAIN YOUR THINKING</div><h3>${s.question}</h3>${s.options.map((o,j)=>`<button class="option ${scenarioReason===j?'selected':''}" data-reason="${j}" aria-pressed="${scenarioReason===j}"><span class="radio"></span>${o}</button>`).join('')}<div class="actions"><button class="btn" data-action="submit-scenario" ${scenarioAction===null||scenarioReason===null?'disabled':''}>Review my reasoning ${icon('arrow',16)}</button></div></div><p class="data-note">Your action is a reflection, not an executed virtual order. No single buy, hold, or sell choice is scored as universally correct.</p></section><aside class="stack"><div class="panel"><h3>Pause. Look at the evidence.</h3><p>What changed?<br>What remains uncertain?<br>Does it affect your original view?<br>What else would you want to know?</p></div><div class="inline-note">${icon('shield',18)}<span>These are controlled learning scenarios. Their price movements are not forecasts.</span></div></aside></div>`}
function report(){let q=Object.values(state.answers).filter(a=>a.correct).length,d=state.decisions.filter(a=>a.correct).length;return `${back('practice','Practice portfolio')}${title('YOUR PRACTICE REPORT','Progress you can explain.')}<div class="twocol"><div class="stack"><div class="panel"><div class="bigicon">${icon('check',30)}</div><h2>Practice complete. Keep your curiosity.</h2><p>You explored a business and practised responding to new information. Here’s what your answers demonstrated.</p><div class="balancegrid"><div><small>Lesson concepts understood</small><strong>${q} / ${Object.keys(state.answers).length||4}</strong></div><div><small>Evidence-based scenario answers</small><strong>${d} / 3</strong></div></div><div class="inline-note">${icon('info',18)}<span>This report reflects these exercises only. It does not certify investment readiness or predict performance.</span></div></div><div class="panel"><h3>Your decisions, revisited</h3>${state.decisions.map(a=>`<div class="reviewitem"><div class="row"><strong>${Engine.scenarios[a.scenario].title}</strong><span class="badge ${a.correct?'':'soon'}">${a.correct?'UNDERSTOOD':'REVISIT'}</span></div><p>You chose: ${esc(a.action)}<br>Your reasoning: ${Engine.scenarios[a.scenario].options[a.reason]}</p><p>${Engine.scenarios[a.scenario].feedback}</p></div>`).join('')}</div><div class="panel"><h3>What would you like to do next?</h3><p>Keep researching, revisit a concept, or explore the stock page. Waiting and gathering more information are valid next steps.</p><div class="footer-actions"><button class="btn" data-go="stock">Explore stock ${icon('arrow',15)}</button><button class="btn secondary" data-go="curriculum">Revisit lessons</button></div><button class="text-link" data-action="reset-practice">Start a fresh practice session ${icon('arrow',14)}</button></div></div><aside class="stack"><div class="panel"><h3>A useful checklist</h3><p>Can I explain the business?<br>Have I compared expectations?<br>What could go wrong?<br>What evidence would change my view?</p></div><div class="panel"><h3>Topics to revisit</h3>${modules.map((m,i)=>`<button class="text-link" style="display:flex;width:100%;text-align:left" data-module="${i}">${icon(state.answers[i]?.correct?'check':'book',15)} ${m.title}</button>`).join('')}</div></aside></div>${note()}`}
function chart(){const series={'1D':[46,45,48,42,44,49,46,55,51,54,58,56,62,60,64,63,61,66],'1M':[30,33,32,39,36,42,37,43,46,49,45,54,51,57,59,55,61,65],'1Y':[15,20,18,24,29,25,36,31,45,41,49,53,46,56,62,58,70,75],'3Y':[9,16,12,19,16,24,34,28,37,46,43,49,67,60,70,80,73,87]};const arr=series[period];return `<svg class="linechart" viewBox="0 0 500 160" preserveAspectRatio="none" role="img" aria-label="Illustrative ${period} stock price chart. Sample data, not real historical returns."><path d="M0 135H500M0 80H500M0 25H500" stroke="#25322a" stroke-dasharray="3 6" fill="none"/><polyline points="${arr.map((v,i)=>`${i*500/(arr.length-1)},${155-v*1.5}`).join(' ')}" fill="none" stroke="#00ce9c" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`}
function stock(){return `${back(state.interfaceMode==='classic'?'explore':'home',state.interfaceMode==='classic'?'Stocks':'First Steps')}<div class="twocol"><div class="stack"><div class="panel"><div class="row"><div class="company" style="margin:0"><div class="companylogo">tcs</div><div><strong>Tata Consultancy Services</strong><small>TCS · IT services · Sample data</small></div></div><button class="iconbutton" data-action="bookmark" aria-label="${state.bookmarked?'Remove from':'Add to'} watchlist" style="color:${state.bookmarked?'var(--green)':'inherit'}">${icon('bookmark')}</button></div><div class="balance" style="margin-top:28px">₹3,200<span class="subtle" style="font-size:10px;letter-spacing:0;margin-left:12px">ILLUSTRATIVE</span></div><span class="positive" style="font-size:12px">Sample price chart · ${period}</span>${chart()}<div class="periods">${['1D','1M','1Y','3Y'].map(p=>`<button class="${period===p?'selected':''}" data-period="${p}">${p}</button>`).join('')}</div><div class="tabs">${['Overview','Financials','Risks'].map(t=>`<button data-stocktab="${t}" class="${stockTab===t?'selected':''}">${t}</button>`).join('')}</div>${stockTab==='Overview'?'<p>TCS is used here as an example of an IT services business. Explore what it does, how to interpret its numbers, and what information could change your assessment.</p><div class="metric"><span>Sample P/E</span><strong>28×</strong></div><div class="metric"><span>Sample peer P/E</span><strong>25×</strong></div>':stockTab==='Financials'?'<p>Illustrative financials, not reported company results.</p><div class="metric"><span>Revenue index · Year 1 → 5</span><strong>100 → 151</strong></div><div class="metric"><span>Sample operating margin</span><strong>24%</strong></div><div class="metric"><span>Scenario 1 revenue growth</span><strong>10%</strong></div>':'<p>Customer spending slowdowns, pressure on operating margins, competition, and changes in market expectations can affect business performance and share prices.</p><div class="concept">A familiar brand and a rising price do not remove the risk of losing money.</div>'}<div class="footer-actions"><button class="btn full" data-action="mock-buy">${Engine.canInvest(state)?'View demo buy flow':'Complete Stocks lessons to invest'} ${icon(Engine.canInvest(state)?'arrow':'lock',16)}</button></div><p class="data-note">Prototype only. No brokerage connection or real transaction.</p></div></div><aside class="stack"><div class="learn-callout"><span class="eyebrow">NEW TO STOCKS?</span><h3>Understand before you invest.</h3><p>Learn the essentials through this company. Then practise with virtual money.</p><button class="btn full" data-action="enroll">${state.enrolled?'Continue learning':'First Steps'} ${icon('arrow',16)}</button><p class="data-note">~10–15 min · No real money</p></div><div class="panel"><h3>Make sense of the numbers.</h3><p>Ask about the sample company, valuation, or the risks in this demo.</p><button class="text-link" data-action="ai">${icon('spark',15)} Ask demo assistant</button></div></aside></div>${note()}`}
function render(){if(page==='welcome'||page==='recommend'){renderWelcome();return;}const views={home,explore,curriculum,lesson:lessonPage,practice,scenario,report,stock,'course-complete':courseComplete};const current=views[page]||home;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-go="${Engine.landing(state)}" aria-label="Groww home"><span class="logo"></span>groww</button><div class="navgroup"><div class="navlabel" style="padding:0 13px 8px">Your investments</div><button class="navitem ${page==='stock'?'active':''}" data-go="${state.interfaceMode==='guided'?'curriculum':'explore'}">${icon('chart')} Stocks</button><button class="navitem" data-action="funds">${icon('pie')} Mutual funds</button><button class="navitem" data-action="fo">${icon('layers')} F&O</button></div><div class="navgroup"><div class="navlabel" style="padding:0 13px 8px">Build your understanding</div><button class="navitem ${['home','curriculum','lesson'].includes(page)?'active':''}" data-action="guided-home">${icon('book')} First Steps</button><button class="navitem ${['practice','scenario','report'].includes(page)?'active':''}" data-action="open-practice">${icon('wallet')} Practice portfolio</button><button class="navitem" data-action="ai">${icon('spark')} Demo assistant</button></div><div class="sidebar-foot"><button class="navitem" data-action="settings" style="padding-left:0">${icon('settings',17)} Settings</button><strong>Learn a little. Understand more.</strong><br>An educational prototype.<br>No real money. No pressure.</div></aside><div class="body"><header class="topbar"><div class="breadcrumb">Groww ${icon('chevron',12)} <strong>${['stock','explore'].includes(page)?'Stocks':'First Steps'}</strong></div><button class="brand mobilebrand" data-go="${Engine.landing(state)}"><span class="logo"></span>groww</button><div class="top-actions"><span class="pill"><i class="dot"></i> EDUCATIONAL PROTOTYPE</span><button class="avatar" data-action="settings" aria-label="Open settings">YOU</button></div></header><main class="content" id="main">${current()}</main></div></div><nav class="bottomnav" aria-label="Main navigation"><button class="active" data-go="${state.interfaceMode==='guided'?'curriculum':'explore'}">${icon('chart',21)}Stocks</button><button data-action="fo">${icon('layers',21)}F&O</button><button data-action="funds">${icon('pie',21)}Mutual Funds</button></nav>`;}
function openSheet(heading,body){modalReturnFocus=document.activeElement;$('#overlay').innerHTML=`<div class="sheet-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" tabindex="-1"><div class="sheethead"><h2 id="sheet-title">${heading}</h2><button class="iconbutton" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;$('.sheet').focus();}
function closeSheet(){$('#overlay').innerHTML='';if(modalReturnFocus&&document.contains(modalReturnFocus))modalReturnFocus.focus();}
function dismissSheet(){if(page==='scenario'&&state.scenario!==renderedScenario)go(state.scenario===3?'report':'practice');else closeSheet();}
function enroll(){if(state.interfaceMode!=='guided'){openSheet('Learn with Groww First Steps',`<p>Switch to a guided experience: finish the four Stocks lessons to unlock demo investing. Your existing progress stays saved.</p><button class="btn full" data-action="enter-guided">Switch to First Steps</button><button class="btn ghost full" style="margin-top:10px" data-action="close">Keep classic</button>`);return;}state.enrolled=true;save();go('curriculum');}
function investmentGate(){if(Engine.canInvest(state))return true;openSheet('Learn first. Then take your next step.',`<div class="bigicon">${icon('lock',27)}</div><p>In Groww First Steps, complete all four Stocks lessons to unlock demo investing.</p><div class="metric"><span>Stocks foundation</span><strong>${state.completed.length} / 4 complete</strong></div><p class="data-note">Review each lesson and its understanding check. Practice scenarios are optional after the course.</p><button class="btn full" data-action="resume-course">Continue Stocks lessons ${icon('arrow',16)}</button>`);return false;}
function tradeSheet(side='buy',mock=false){if(mock&&!investmentGate())return;const price=mock?3200:state.price;openSheet(mock?'Demo purchase':side==='buy'?'Buy with virtual money':'Sell virtual shares',`<span class="pill">${mock?'PROTOTYPE · NO REAL TRANSACTION':'PRACTICE · VIRTUAL MONEY'}</span><div class="company"><div class="companylogo">tcs</div><div><strong>TCS</strong><small>${money(price)} per whole ${mock?'demo':'practice'} share</small></div></div><p>${mock?'Explore a simulated order review. No account or payment is connected.':side==='buy'?`Available virtual cash: ${money(state.cash)}`:`Available practice shares: ${state.units}`}</p><label class="fieldlabel" for="quantity">Number of whole shares</label><input id="quantity" class="input" type="number" inputmode="numeric" min="1" step="1" value="1"><div class="metric"><span>Order value</span><strong id="order-value">${money(price)}</strong></div><div id="trade-error" class="error" role="alert"></div><button class="btn full" data-action="${mock?'review-mock':side==='buy'?'confirm-buy':'confirm-sell'}">${mock?'Review demo order':side==='buy'?'Confirm practice buy':'Confirm practice sell'} ${icon('arrow',15)}</button><p class="data-note">${mock?'This demonstration never places a real order.':'Whole shares only. No fees modelled. The unused balance remains virtual cash.'}</p>`);$('#quantity').dataset.price=price;}
const aiAnswers={business:'In this example, TCS earns revenue by providing technology and consulting services to businesses. Revenue comes from customers; profit is what remains after costs. Start by understanding customer demand and how the company delivers its services.',pe:'P/E compares share price with earnings per share. A sample P/E of 28× means paying ₹28 per ₹1 of annual earnings per share. A higher P/E can reflect stronger expectations, but does not guarantee stronger returns. Compare similar companies and matching earnings periods.',risk:'The demo highlights customer spending slowdowns, pressure on margins, competition, and high market expectations. A familiar company can still lose value. Consider what evidence would change your assessment.',compare:'In our fictional dataset, TCS has a P/E of 28× and Infosys 25×. This means a higher price per rupee of earnings for TCS. The comparison alone does not establish which is a better investment; growth, risk, quality, and the earnings basis matter.',price:'This prototype has no live market feed or current news. Its three scenario price changes (+4%, −8%, −3%) are predefined illustrations. They cannot explain actual recent stock movements or predict returns.',fallback:'I can explain the business example, P/E, risks, peer comparison, or how this simulation works. I do not have live news, market data, personal financial information, or the ability to recommend an investment.'};
function ai(){openSheet('Ask the demo assistant',`<span class="pill">SCRIPTED EXPLAINER · SAMPLE DATA ONLY</span><p>A little context can make a number easier to understand.</p><button class="suggestion" data-ai="business">How does this company make money?</button><button class="suggestion" data-ai="pe">Explain the P/E ratio simply</button><button class="suggestion" data-ai="risk">What risks should I consider?</button><button class="suggestion" data-ai="compare">Compare the sample peer valuations</button><label class="fieldlabel" for="ai-input">Or ask a question</label><input class="input" id="ai-input" placeholder="What does P/E mean?" style="font-size:13px" maxlength="300"><button class="text-link" data-action="ask">Ask ${icon('arrow',15)}</button><div id="ai-response" aria-live="polite"></div>`);}
function settings(){openSheet('Settings',`<div class="eyebrow">INVESTING EXPERIENCE</div><p>Choose the experience that feels right for you.</p><button class="option ${state.experience==='new'?'selected':''}" data-profile="new"><span class="radio"></span><span>I’m new to investing<small class="setting-detail">Show me the guided starting options.</small></span></button><button class="option ${state.experience==='pro'?'selected':''}" data-profile="pro"><span class="radio"></span><span>I’m experienced<small class="setting-detail">Take me directly to classic Stocks.</small></span></button><div class="eyebrow" style="margin-top:24px">YOUR INTERFACE</div><button class="option ${state.interfaceMode==='guided'?'selected':''}" data-interface="guided"><span class="radio"></span><span>Groww First Steps<small class="setting-detail">Finish Stocks lessons to unlock demo investing.</small></span></button><button class="option ${state.interfaceMode==='classic'?'selected':''}" data-interface="classic"><span class="radio"></span><span>Classic Groww<small class="setting-detail">Browse stocks and use the demo buy flow directly.</small></span></button><p class="data-note">Switching keeps your lessons and practice progress. Your choice is remembered on this browser.</p><button class="btn ghost full" data-action="reset-all">Reset all demo progress</button>`);}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;if(el.dataset.go){go(el.dataset.go);return;}if(el.dataset.module!==undefined){const i=+el.dataset.module;if(state.interfaceMode==='guided'&&i>0&&!state.completed.includes(i-1)){toast(`Complete “${modules[i-1].title}” to unlock this lesson.`);return;}lesson=i;go('lesson');return;}if(el.dataset.profile){Engine.selectExperience(state,el.dataset.profile);save();go(Engine.landing(state));return;}if(el.dataset.interface){Engine.selectInterface(state,el.dataset.interface);save();go(Engine.landing(state));return;}if(el.dataset.answer!==undefined){selection=+el.dataset.answer;render();return;}if(el.dataset.period){period=el.dataset.period;render();return;}if(el.dataset.stocktab){stockTab=el.dataset.stocktab;render();return;}if(el.dataset.decision){scenarioAction=el.dataset.decision;render();return;}if(el.dataset.reason!==undefined){scenarioReason=+el.dataset.reason;render();return;}if(el.dataset.ai){$('#ai-response').innerHTML=`<div class="aianswer">${aiAnswers[el.dataset.ai]}</div>`;return;}const action=el.dataset.action;
switch(action){case'guided-home':if(state.interfaceMode==='guided')go('home');else enroll();break;case'choose-experience':go('welcome');break;case'enter-guided':Engine.selectInterface(state,'guided');state.enrolled=true;save();go('curriculum');break;case'resume-course':state.enrolled=true;save();go('curriculum');break;case'enroll':enroll();break;case'close':dismissSheet();break;case'settings':settings();break;case'ai':ai();break;case'ask':{let q=$('#ai-input').value.toLowerCase().trim();if(!q){toast('Enter a question first.');break;}let k=/buy|sell|recommend|should i|best stock/.test(q)?'fallback':/fall|recent|today|price|market|simulation|simulat/.test(q)?'price':/compare|infosys|peer/.test(q)?'compare':/p\/e|pe ratio|valuation|earnings/.test(q)?'pe':/risk|wrong|loss/.test(q)?'risk':/business|revenue|money|company/.test(q)?'business':'fallback';$('#ai-response').innerHTML=`<div class="aianswer">${aiAnswers[k]}</div>`;break;}
case'soon-funds':case'soon-etfs':openSheet(action==='soon-funds'?'Mutual funds · Track preview':'ETFs · Track preview',`<span class="pill">COMING SOON</span><p>${action==='soon-funds'?'A future track covering how funds work, diversification, costs, and regular investing.':'A future track covering index baskets, exchange trading, diversification, and costs.'}</p><p>The Stocks foundation is the complete learning track in this prototype.</p><button class="btn full" data-action="enroll">Explore the Stocks track ${icon('arrow',15)}</button>`);break;
case'funds':case'fo':openSheet(action==='funds'?'Mutual funds':'Futures & Options',`<p>This case-study prototype focuses on stock learning and practice. ${action==='fo'?'Derivatives trading and activation are outside its scope.':'Fund discovery and investing are outside its scope.'}</p><button class="btn full" data-go="home">Return to learning</button>`);break;
case'check-answer':if(selection!==null&&!checked){checked=true;if(!state.completed.includes(lesson))state.completed.push(lesson);state.answers[lesson]={selected:selection,correct:selection===modules[lesson].correct};save();render();}break;
case'next-module':if(lesson<3){lesson++;selection=null;checked=false;render();window.scrollTo(0,0);}else go('course-complete');break;
case'start-practice':case'open-practice':if(!Engine.stocksComplete(state)&&state.interfaceMode==='guided'){if(action==='open-practice')go('curriculum');toast('Complete the four lessons to unlock guided practice.');}else go('practice');break;
case'virtual-buy':tradeSheet('buy');break;case'virtual-sell':tradeSheet('sell');break;
case'confirm-buy':case'confirm-sell':try{Engine.trade(state,action==='confirm-buy'?'buy':'sell',Number($('#quantity').value));save();go('practice');toast('Practice transaction complete. No real money used.');}catch(err){$('#trade-error').textContent=err.message;}break;
case'scenario':if(state.scenario===3)go('report');else if(state.transactions.length)go('scenario');break;
case'submit-scenario':{const i=state.scenario;try{Engine.decide(state,scenarioAction,scenarioReason);save();openSheet('A moment to reflect',`<span class="badge ${state.decisions[i].correct?'':'soon'}">${state.decisions[i].correct?'EVIDENCE-BASED REASONING':'SOMETHING TO REVISIT'}</span><p>${Engine.scenarios[i].feedback}</p><div class="concept">You chose “${esc(scenarioAction)}”. The feedback assesses your reasoning, not whether that action would make money.</div><button class="btn full" data-action="next-scenario">${state.scenario===3?'View my practice report':'Next scenario'} ${icon('arrow',16)}</button>`);}catch(err){toast(err.message);}break;}
case'next-scenario':go(state.scenario===3?'report':'scenario');break;
case'bookmark':state.bookmarked=!state.bookmarked;save();render();toast(state.bookmarked?'Added to your demo watchlist.':'Removed from your demo watchlist.');break;
case'history':openSheet('Practice activity',state.transactions.length?`<div class="history">${state.transactions.map(t=>`<div class="metric"><span>${t.side==='buy'?'Bought':'Sold'} ${t.units} TCS · ${money(t.price)} each</span><strong>${money(t.units*t.price)}</strong></div>`).join('')}</div><p class="data-note">Virtual transactions only. Scenario reflections do not place orders.</p>`:'<p>No practice transactions yet. Start with your first virtual purchase.</p>');break;
case'mock-buy':tradeSheet('buy',true);break;
case'review-mock':{if(!investmentGate())break;const n=Number($('#quantity').value);if(!Number.isInteger(n)||n<1||n>100000){$('#trade-error').textContent='Enter a whole number from 1 to 100,000.';break;}openSheet('Review demo order',`<span class="pill">PROTOTYPE · NO REAL TRANSACTION</span><div class="metric"><span>Company</span><strong>TCS</strong></div><div class="metric"><span>Whole shares</span><strong>${n}</strong></div><div class="metric"><span>Sample price</span><strong>₹3,200</strong></div><div class="metric"><span>Illustrative value</span><strong>${money(n*3200)}</strong></div><p>No payment, account, fees, or real execution is connected. This order will not change your practice portfolio.</p><button class="btn full" data-action="finish-mock">Confirm demo order</button>`);break;}
case'finish-mock':if(!investmentGate())break;openSheet('Demo complete',`<div class="bigicon">${icon('check',28)}</div><h3>Prototype — No real transaction</h3><p>You explored the order journey. No money moved and no shares were purchased.</p><button class="btn full" data-go="stock">Back to the stock</button>`);break;
case'reset-practice':openSheet('Start practice again?',`<p>This resets your virtual balance to ₹10,000 and clears practice trades and scenario answers. Your lesson progress stays saved.</p><button class="btn full" data-action="confirm-reset-practice">Reset practice session</button>`);break;
case'confirm-reset-practice':{const fresh=Engine.initial();for(const k of ['cash','units','price','invested','transactions','scenario','applied','decisions'])state[k]=fresh[k];save();go('practice');break;}
case'reset-all':openSheet('Reset your progress?',`<p>This removes all locally saved lessons, answers, and practice transactions. You’ll start with the experience choice again.</p><button class="btn full" data-action="confirm-reset">Reset everything</button><button class="btn ghost full" style="margin-top:10px" data-action="close">Keep my progress</button>`);break;
case'confirm-reset':state=Engine.initial();save();go('welcome');toast('Your demo has been reset.');break;
}});
document.addEventListener('input',e=>{if(e.target.id==='quantity'){const n=Number(e.target.value),v=n*Number(e.target.dataset.price);$('#order-value').textContent=Number.isFinite(v)&&n>=0?money(v):'—';$('#trade-error').textContent='';}});
document.addEventListener('keydown',e=>{const sheet=$('.sheet');if(!sheet)return;if(e.key==='Escape'){e.preventDefault();dismissSheet();}if(e.key==='Tab'){const els=[...sheet.querySelectorAll('button:not(:disabled), input, [tabindex="0"]')];const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===sheet)){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===sheet)){e.preventDefault();first.focus();}}if(e.key==='Enter'&&e.target.id==='ai-input')$('[data-action="ask"]').click();});
function renderWelcome(){const intro=page==='welcome';$('#app').innerHTML=`<div class="onboarding ${intro?'':'recommendation'}"><header class="onboard-header"><div class="brand"><span class="logo"></span>groww</div><span class="pill"><i class="dot"></i> EDUCATIONAL PROTOTYPE</span></header><main class="onboard-main"><section class="onboard-story"><span class="tag">${icon('spark',13)} YOUR JOURNEY, YOUR PACE</span><h1>${intro?'Every investor<br>starts somewhere.':'A little learning.<br>A stronger start.'}</h1><p>${intro?'Let’s make Groww feel right for you. Tell us where you are in your investing journey.':'Start with Groww First Steps: learn the essentials of each investment type before you take the next step.'}</p><div class="onboard-illustration" aria-hidden="true"><div class="path-line"></div><div class="path-stop first">${icon('book',27)}<span>Understand</span></div><div class="path-stop second">${icon('wallet',27)}<span>Practice</span></div><div class="path-stop third">${icon('chart',27)}<span>Invest</span></div></div><div class="onboard-caption">${icon('shield',17)} Your choice. Your pace. Change it anytime.</div></section><section class="onboard-choices">${intro?`<div class="eyebrow">LET’S PERSONALISE YOUR EXPERIENCE</div><h2>How familiar are you<br>with investing?</h2><p class="choice-intro">There’s no right answer. Just your starting point.</p><button class="profile-card" data-profile="new"><span class="track-icon">${icon('book',24)}</span><span><strong>I’m new to investing</strong><small>I’d like a little guidance as I get started.</small></span>${icon('arrow',20)}</button><button class="profile-card" data-profile="pro"><span class="track-icon purple">${icon('chart',24)}</span><span><strong>I’m experienced</strong><small>I know my way around. Take me to Stocks.</small></span>${icon('arrow',20)}</button><p class="onboard-foot">You can switch between beginner and experienced in Settings. Your learning progress will stay with you.</p>`:`<button class="back" data-go="welcome">${icon('back',15)} Change experience</button><div class="eyebrow">A GOOD PLACE TO BEGIN</div><h2>Choose your way<br>into investing.</h2><div class="recommended-card"><div class="row"><span class="track-icon">${icon('book',24)}</span><span class="badge">RECOMMENDED FOR YOU</span></div><h3>Groww First Steps</h3><p>Learn first. Invest with understanding.</p><ul><li>Choose what you want to invest in</li><li>Complete its short, guided lessons</li><li>Unlock investing when the course is complete</li></ul><button class="btn full" data-interface="guided">Start with First Steps ${icon('arrow',17)}</button></div><button class="profile-card classic-choice" data-interface="classic"><span><strong>Continue with classic Groww</strong><small>Use the familiar interface and explore directly.</small></span>${icon('arrow',20)}</button><p class="onboard-foot">You can change your interface in Settings anytime. All transactions in this prototype are simulated.</p>`}</section></main><footer class="onboard-footer">An independent Groww-inspired prototype · No real transactions</footer></div>`;}
function explore(){return `${title('CLASSIC GROWW · SAMPLE DATA','Stocks',`<button class="text-link" data-action="settings">Settings ${icon('settings',15)}</button>`)}<div class="market-strip"><div><span>NIFTY 50 · SAMPLE</span><strong>24,850.00</strong><small class="positive">+102.40 (0.41%)</small></div><div><span>SENSEX · SAMPLE</span><strong>81,200.00</strong><small class="positive">+285.60 (0.35%)</small></div></div><div class="twocol"><div class="stack"><div class="section-heading" style="margin-top:10px"><h2>Explore stocks</h2><span class="subtle">One complete stock demo</span></div><button class="stock-discovery panel" data-go="stock"><div class="row"><div class="company" style="margin:0"><div class="companylogo">tcs</div><div><strong>Tata Consultancy Services</strong><small>TCS · IT services</small></div></div>${icon('chevron',18)}</div><div class="balance" style="font-size:28px">₹3,200</div><div class="row"><span class="subtle">Illustrative price · Not live</span><span class="positive" style="font-size:12px">View stock →</span></div>${chart()}</button><div class="panel"><h3>Your watchlist</h3>${state.bookmarked?`<button class="module" data-go="stock"><span class="companylogo">tcs</span><span><strong>TCS</strong><small>₹3,200 · Sample price</small></span><span class="end">${icon('chevron',16)}</span></button>`:'<p>Open a stock and tap the bookmark to keep it here.</p>'}</div></div><aside class="stack"><div class="panel"><span class="eyebrow">YOUR EXPERIENCE</span><h3 style="margin-top:13px">Classic, just how you like it.</h3><p>Explore the stock, review its sample financials, and open the demo buy flow directly.</p><span class="pill">${state.experience==='pro'?'EXPERIENCED INVESTOR':'BEGINNER · CLASSIC INTERFACE'}</span></div><div class="learn-callout"><span class="eyebrow">A LITTLE GUIDANCE?</span><h3>Meet Groww First Steps.</h3><p>A guided path from learning the basics to unlocking stock investing.</p><button class="text-link" data-action="guided-home">Explore First Steps ${icon('arrow',15)}</button></div></aside></div>${note()}`;}
function courseComplete(){return `${back('curriculum','Stocks foundation')}<div class="completion-card panel"><div class="bigicon">${icon('check',30)}</div><span class="eyebrow">4 OF 4 LESSONS COMPLETE</span><h1 class="lesson-title">You’ve unlocked<br>stock investing.</h1><p class="lesson-sub">You’ve covered the business, growth, valuation, and risk. The demo investment flow is now available in First Steps.</p><div class="completion-topics">${modules.map(m=>`<span>${icon('check',16)} ${m.title}</span>`).join('')}</div><div class="footer-actions"><button class="btn" data-go="stock">Explore stock & invest ${icon('arrow',16)}</button><button class="btn secondary" data-go="practice">Practice with virtual money</button></div><div class="inline-note" style="margin-top:24px">${icon('info',18)}<span>Course completion unlocks the prototype flow. It is not a recommendation or a guarantee of investment readiness. No real money is used.</span></div></div>${note()}`;}
render();
